"""Add six scrub-typhus and four leptospirosis questions."""
from create_id_dengue import rows,q,WM,SM,UM,MD,MQ,DG,DP,DT,WA
from qbank_authoring import ref,finalize
ST=ref('CDC: Clinical Overview of Scrub Typhus','https://www.cdc.gov/typhus/hcp/clinical-overview/clinical-overview-of-scrub-typhus.html')
SC=ref('INTREST Trial: IV Doxycycline, Azithromycin or Both for Severe Scrub Typhus, 2023','https://www.nejm.org/doi/full/10.1056/NEJMoa2208449')
LE=ref('CDC: Clinical Overview of Leptospirosis, 2026','https://www.cdc.gov/leptospirosis/hcp/clinical-overview/')
LD=ref('CDC Yellow Book: Leptospirosis','https://www.cdc.gov/yellow-book/hcp/travel-associated-infections-diseases/leptospirosis.html')
q('A farmer has fever, thrombocytopenia, transaminitis and a painless dark eschar in the groin after field exposure. Which diagnosis is most likely?', 'Scrub typhus',[
 ('Enteric fever as specifically established by the eschar','An eschar is not the characteristic enteric-fever lesion.'),('Dengue as the only possible cause of thrombocytopenia','The eschar and exposure point toward an alternative.'),('Uncomplicated malaria as established by a normal blood smear','The overall pattern needs a different targeted assessment.')],
 'An eschar can redirect the acute undifferentiated-fever differential', '**Orientia infection follows infected chigger exposure.**',['Examine concealed skin sites with consent and appropriate privacy.','Rash, nodes and organ dysfunction can accompany the illness.'], '**Treat a high-probability case promptly and obtain appropriate tests.**',['Do not await late serological confirmation in severe disease.','Assess pulmonary, neurological and renal involvement.'],[['Exposure','Chigger-associated field exposure'],['Clue','Painless eschar'],['Syndrome','Fever with possible multiorgan involvement']],[ST],style='clinical_scenario')
q('Does absence of an eschar exclude scrub typhus?', 'No; the lesion may be absent, small or missed, and the syndrome and exposure still matter',[
 ('Yes, it is present in every confirmed case','Its sensitivity is incomplete.'),('Only a positive Weil-Felix test can replace the absent lesion','That test has major limitations and is not definitive.'),('No eschar means antibiotic treatment can never be considered','High clinical probability can still justify prompt therapy.')],
 'A useful specific clue can still be insensitive', '**Scrub typhus often requires an epidemiological and syndromic assessment.**',['Severe disease can present with ARDS, encephalopathy or renal dysfunction.','A careful skin examination can find an overlooked lesion.'], '**Use suitable molecular and serological evidence.**',['Early antibody tests may be negative.','Reassess alternative tropical infections and coinfection when indicated.'],[['Eschar present','Helpful clue'],['Eschar absent','Does not exclude'],['Diagnosis','Exposure, syndrome and appropriate tests']],[ST])
q('Which test can provide specific early evidence of scrub typhus when available?', 'PCR on an appropriate blood or eschar specimen',[
 ('A single low Weil-Felix titer as definitive proof','Its performance is inadequate for that conclusion.'),('A positive Widal result as an Orientia-specific test','It is not a scrub-typhus assay.'),('A normal leukocyte count as exclusion','Routine blood counts do not exclude the infection.')],
 'Direct detection and serology have different diagnostic windows', '**Molecular testing can identify Orientia DNA.**',['Specimen and illness timing influence yield.','Paired serology can demonstrate a recent antibody change.'], '**Interpret a single antibody result with local background and timing.**',['Antibodies can persist after earlier exposure.','Do not delay treatment of a high-risk likely case while waiting for confirmation.'],[['PCR','Specific organism evidence'],['Early serology','Can be negative'],['Paired serology','Recent change supports acute infection']],[ST])
q('Which antibiotic is the usual treatment of choice for suspected scrub typhus when suitable?', 'Doxycycline',[
 ('Ceftriaxone alone as reliable Orientia-directed therapy','Conventional beta-lactam coverage is not the preferred directed treatment.'),('Vancomycin alone','It does not provide appropriate Orientia coverage.'),('Fluconazole','It is an antifungal and does not treat this bacterial infection.')],
 'Routine empirical sepsis regimens may leave a rickettsial-type gap', '**Orientia requires an active intracellular-targeted regimen.**',['Doxycycline is the usual first choice.','Patient circumstances can support alternatives such as azithromycin.'], '**Recognize the diagnosis early enough to provide active treatment.**',['Review organ involvement and supportive-care needs.','A rapid clinical response supports but does not independently prove the diagnosis.'],[['Preferred when suitable','Doxycycline'],['Alternative context','Selected azithromycin use'],['Pitfall','Assuming every broad beta-lactam covers Orientia']],[ST])
q('What did the Indian INTREST randomized trial show for severe scrub typhus?', 'IV doxycycline plus azithromycin improved the composite outcome compared with either IV drug alone',[
 ('The combination proved a separate mortality reduction in every subgroup','The main demonstrated result concerned the composite endpoint.'),('Ceftriaxone monotherapy was superior to both study drugs','That was not the tested comparison.'),('All mild scrub cases require intensive-care IV combination treatment','The study involved severe disease and should not be generalized indiscriminately.')],
 'Evidence must be interpreted in the enrolled population and measured endpoint', '**The trial enrolled severe disease with organ involvement.**',['The composite included death, persistent complications and persistent fever.','The result supports combination consideration in severe illness.'], '**Apply it alongside current local specialist guidance.**',['Monitor adverse effects and interactions.','Do not extrapolate a severe-disease trial to every uncomplicated presentation.'],[['Population','Severe scrub typhus'],['Comparison','IV combination versus either alone'],['Result','Better primary composite outcome']],[SC])
q('A patient with scrub typhus develops severe hypoxemia and diffuse lung injury. What is the best management principle?', 'Provide active anti-Orientia therapy and appropriate respiratory/organ support rather than treat thrombocytopenia alone',[
 ('Platelet transfusion alone eradicates the infection','It does not.'),('A normal chest examination rules out serious pulmonary involvement','Early findings can be subtle despite hypoxemia.'),('Delay treatment until an eschar appears','An eschar may never be found.')],
 'Scrub typhus can be a multiorgan critical illness', '**ARDS, shock and CNS involvement can occur.**',['Severity requires escalation of care.','Evaluate other causes and coinfection when the course suggests them.'], '**Treat both pathogen and physiological complications.**',['Use lung-protective support when indicated.','Review severe-disease antimicrobial strategy with specialist input.'],[['Pathogen','Active Orientia treatment'],['Lungs','Respiratory support'],['Whole patient','Shock and other organ assessment']],[ST,SC],style='clinical_scenario')
q('After floodwater exposure, a patient develops fever, marked calf pain, conjunctival suffusion, jaundice and AKI. Which infection is most likely?', 'Leptospirosis',[
 ('Uncomplicated viral hepatitis as the complete explanation','The exposure, calf pain, suffusion and renal involvement suggest leptospirosis.'),('Dengue as definitively established by jaundice alone','The syndrome and exposure point toward a different differential.'),('Latent TB infection','It does not explain this acute multisystem syndrome.')],
 'Contaminated water can transmit a zoonotic spirochete', '**Leptospira enters through mucosa or damaged skin after exposure to infected-animal urine.**',['Severe disease can involve liver, kidneys, lungs and circulation.','Weil-type disease describes important severe hepatic/renal involvement.'], '**Start indicated therapy promptly while confirming the diagnosis.**',['Assess urine output, potassium and respiratory status.','Do not wait for serology if the clinical suspicion is high.'],[['Exposure','Animal-urine-contaminated water'],['Clues','Calf pain and conjunctival suffusion'],['Severe disease','Renal, hepatic and pulmonary involvement']],[LE,LD],style='clinical_scenario')
q('Which leptospirosis testing strategy best accounts for illness timing?', 'Early blood PCR with appropriately timed serology, and urine PCR becoming useful later',[
 ('A negative first-week antibody test permanently excludes the disease','Antibody sensitivity rises later.'),('Urine culture alone always provides an immediate answer','Conventional culture is slow and not the sole practical strategy.'),('A positive malaria antigen test is a specific Leptospira test','These detect different infections.')],
 'Organism distribution and host response change through the illness', '**Blood PCR is useful during the early leptospiremic phase.**',['Serology becomes more sensitive in the second week.','Urine PCR can help after the first week.'], '**Use paired samples when needed.**',['Interpret a single result with exposure and symptoms.','Do not delay a justified treatment decision for a late confirmation.'],[['Early','Blood PCR'],['Later','Serology and selected urine PCR'],['Negative early serology','Does not rule out']],[LD])
q('A patient with suspected severe leptospirosis has jaundice, renal failure and pulmonary hemorrhage. Which treatment approach is appropriate?', 'Prompt IV active therapy such as penicillin or ceftriaxone plus intensive organ support',[
 ('Oral rehydration alone regardless of organ failure','The illness is severe and can require critical care.'),('Wait for MAT seroconversion before treatment','This creates an avoidable delay.'),('Use an antifungal as the sole pathogen treatment','Leptospira is a bacterium.')],
 'Severe leptospirosis requires more than antimicrobial selection', '**IV penicillin or ceftriaxone are recognized options.**',['Respiratory hemorrhage, shock and AKI can be life-threatening.','Drug and dose are selected for the patient and local protocol.'], '**Support oxygenation, circulation and renal function.**',['Dialysis may be necessary for standard indications.','Assess bleeding and avoid excess fluid in pulmonary involvement.'],[['Antimicrobial','Prompt IV active drug'],['Lung','Hemorrhage and respiratory support'],['Kidney','Electrolytes, volume and possible RRT']],[LE],style='clinical_scenario')
q('Which statement about severe pulmonary leptospirosis is correct?', 'Life-threatening pulmonary hemorrhage can occur even without the full classic jaundice/renal-failure triad',[
 ('Severe lung disease requires profound jaundice in every case','The full classic syndrome need not be present.'),('Hemoptysis excludes leptospirosis','Pulmonary hemorrhage is a recognized severe manifestation.'),('Antibiotics alone remove the need for respiratory support','Support is often essential.')],
 'A missing classical feature must not exclude an organ-threatening presentation', '**Leptospirosis has a broad severity spectrum.**',['Exposure and the evolving multisystem picture guide suspicion.','Pulmonary disease can deteriorate rapidly.'], '**Treat the high-risk syndrome and confirm with timing-appropriate tests.**',['Assess oxygenation and bleeding severity.','Consider competing pulmonary-renal and infectious diagnoses in parallel.'],[['Classic syndrome','Not obligatory'],['Pulmonary hemorrhage','Recognized severe form'],['Care','Prompt treatment and critical support']],[LE,LD])

